35	// OpenPath opens a git repository with object alternates enabled.
36	// The caller owns the returned repository and must close it.
37	func OpenPath(repoRoot string) (*git.Repository, error) {
38		repo, err := openPathWithAlternates(repoRoot)
39		if err != nil {
40			if hasAlternates, altErr := hasObjectAlternates(repoRoot); altErr == nil && hasAlternates {
41				return nil, fmt.Errorf("failed to open repository with alternates support: %w", err)
42			}
43	
44			// Intentional PlainOpen fallback for unusual layouts that do not use
45			// alternates. Repositories with alternates must not silently downgrade
46			// because PlainOpen cannot read absolute alternate object directories.
47			if fallbackRepo, fallbackErr := git.PlainOpen(repoRoot); fallbackErr == nil {
48				return fallbackRepo, nil
49			}
50			return nil, fmt.Errorf("failed to open repository: %w", err)
51		}
52		return repo, nil
53	}
54	
55	func hasObjectAlternates(repoRoot string) (bool, error) {
56		repoRoot, err := filepath.Abs(repoRoot)
57		if err != nil {
58			return false, fmt.Errorf("resolve repository root: %w", err)
59		}
60	
61		dotGitPath, err := resolveDotGitPath(repoRoot)
62		if err != nil {
63			return false, fmt.Errorf("resolve .git path: %w", err)
64		}
65	
66		commonGitPath, err := resolveCommonGitPath(dotGitPath)
67		if err != nil {
68			return false, fmt.Errorf("resolve common git path: %w", err)
69		}
70	
71		candidates := []string{filepath.Join(dotGitPath, "objects", "info", "alternates")}
72		if commonGitPath != "" {
73			candidates = append(candidates, filepath.Join(commonGitPath, "objects", "info", "alternates"))
74		}
75		for _, candidate := range candidates {
76			if _, err := os.Stat(candidate); err == nil {
77				return true, nil
78			} else if !errors.Is(err, os.ErrNotExist) {
79				return false, fmt.Errorf("stat alternates file: %w", err)
80			}
81		}
82		return false, nil
83	}
