85	func openPathWithAlternates(repoRoot string) (*git.Repository, error) {
86		repoRoot, err := filepath.Abs(repoRoot)
87		if err != nil {
88			return nil, fmt.Errorf("resolve repository root: %w", err)
89		}
90	
91		dotGitPath, err := resolveDotGitPath(repoRoot)
92		if err != nil {
93			return nil, err
94		}
95	
96		commonGitPath, err := resolveCommonGitPath(dotGitPath)
97		if err != nil {
98			return nil, err
99		}
100	
101		// Wrap the git-dir filesystems so relative alternate object directories are
102		// rewritten to absolute paths on read; go-git cannot follow relative
103		// alternates on its own. The alternates file lives under the common git dir
104		// for linked worktrees, so wrap both.
105		dotGitFS := wrapAlternatesRewrite(osfs.New(dotGitPath, osfs.WithBoundOS()))
106		var commonGitFS billy.Filesystem
107		if commonGitPath != "" {
108			commonGitFS = wrapAlternatesRewrite(osfs.New(commonGitPath, osfs.WithBoundOS()))
109		}
110	
111		repositoryFS := dotgit.NewRepositoryFilesystem(dotGitFS, commonGitFS)
112		// Shared clones write absolute object directories to objects/info/alternates;
113		// an OS-rooted filesystem lets go-git follow those paths outside .git.
114		storage := gitfilesystem.NewStorageWithOptions(
115			repositoryFS,
116			cache.NewObjectLRUDefault(),
117			gitfilesystem.Options{
118				AlternatesFS: newAlternatesFilesystem(),
119			},
120		)
121	
122		// go-git's filesystem storer cannot read the reftable ref backend: it reads
123		// refs from .git/refs, packed-refs and .git/HEAD, none of which are
124		// authoritative in a reftable repository, and its extension check rejects
125		// extensions.refstorage=reftable outright. Route ref operations through the
126		// git CLI for such repositories while keeping object storage on go-git.
127		worktreeFS := osfs.New(repoRoot, osfs.WithBoundOS())
128		if repoUsesReftable(dotGitPath, commonGitPath) {
129			repo, err := git.Open(newReftableStorer(storage, dotGitPath), worktreeFS)
130			if err != nil {
131				_ = storage.Close()
132				return nil, fmt.Errorf("open reftable repository storage: %w", err)
133			}
134			return repo, nil
135		}
136	
137		repo, err := git.Open(storage, worktreeFS)
138		if err != nil {
139			_ = storage.Close()
140			return nil, fmt.Errorf("open repository storage: %w", err)
141		}
142		return repo, nil
143	}
