145	func resolveDotGitPath(repoRoot string) (string, error) {
146		gitPath := filepath.Join(repoRoot, gitDir)
147		info, err := os.Stat(gitPath)
148		if err != nil {
149			return "", fmt.Errorf("stat .git path: %w", err)
150		}
151		if info.IsDir() {
152			return gitPath, nil
153		}
154	
155		content, err := os.ReadFile(gitPath) //nolint:gosec // gitPath is resolved from the git worktree root.
156		if err != nil {
157			return "", fmt.Errorf("read .git file: %w", err)
158		}
159	
160		line, _, _ := strings.Cut(string(content), "\n")
161		gitdir, ok := strings.CutPrefix(strings.TrimSpace(line), "gitdir:")
162		if !ok {
163			return "", errors.New(".git file has no gitdir prefix")
164		}
165	
166		gitdir = strings.TrimSpace(gitdir)
167		if filepath.IsAbs(gitdir) {
168			return filepath.Clean(gitdir), nil
169		}
170		return filepath.Clean(filepath.Join(repoRoot, gitdir)), nil
171	}
172	
173	func resolveCommonGitPath(dotGitPath string) (string, error) {
174		content, err := os.ReadFile(filepath.Join(dotGitPath, "commondir")) //nolint:gosec // dotGitPath is resolved from the git worktree root.
175		if errors.Is(err, os.ErrNotExist) {
176			return "", nil
177		}
178		if err != nil {
179			return "", fmt.Errorf("read commondir file: %w", err)
180		}
181	
182		commonPath := strings.TrimSpace(string(content))
183		if commonPath == "" {
184			return "", nil
185		}
186		if filepath.IsAbs(commonPath) {
187			return filepath.Clean(commonPath), nil
188		}
189		return filepath.Clean(filepath.Join(dotGitPath, commonPath)), nil
190	}
